//! Pipeline outputs (`github.com/Chaintable/pipeline`) regenerated by
//! replaying blocks on an archive: block files (transactions, traces,
//! events), headers and state diffs, uploaded as `pipeline-compactor`
//! bundles.
//!
//! Everything here is chain-agnostic. A chain plugs in its block replay
//! through [`chain::PipelineChain`]; the replay builds the outputs with the
//! shared [`inspector`], [`convert`] and [`build`] pieces.

pub(crate) mod blocks;
pub(crate) mod build;
pub(crate) mod bundle;
pub(crate) mod chain;
pub(crate) mod convert;
pub(crate) mod export;
pub(crate) mod inspector;
pub(crate) mod s3;
pub(crate) mod types;

pub use bundle::{Resource, BUNDLE_SIZE};
pub use chain::Chain;
pub use export::{bundle_range, export_bundles, ExportConfig};
pub use s3::S3Target;
